    aS+=(w+h)*wt;iS+=iw*wt;hS+=h*wt;
  }
  const act=aS/9,inh=iS/9,harm=hS/9;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=(Math.sin(sx*0.08-sy*0.06+t*1.5)+Math.sin(sx*0.05+sy*0.09-t*1.8))/2*0.3;
  const bg3=(Math.sin(sx*0.15+sy*0.12+t*2.5)+Math.cos(sx*0.1-sy*0.18-t*3))/2*0.15;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
