  const ring2=Math.sin(dist*0.1+t*1.5)*Math.exp(-dist*0.008)*0.2;
  const lap=Math.sin(sx*0.1+1)*Math.sin(sy*0.1+2)+Math.sin((sx+sy)*0.08+t)*0.5+Math.sin((sx-sy)*0.06-t*1.5)*0.3;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+harm*0.5+ring1+ring2+lap*0.15)*2.0);
  const c1=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const c2=Math.tanh((Math.sin(sx*0.08+1)*Math.sin(sy*0.08+2)+Math.sin((sx-sy)*0.12-t*0.8)*0.4)*1.2)*0.2;
  const blend=reaction*0.7+(c1+c2)*0.2+harm*0.1;
